"""Temporary one-shot asset seeder for the readable opportunities generator.
It contains compressed DATA/CSS only; no executable site logic is encoded.
After the generated files are committed, remove this file and its build_site call.
"""
from pathlib import Path
import base64, zlib
ROOT=Path(__file__).resolve().parents[1]
DATA_Z=""
CSS_Z=""
(ROOT/'data'/'opportunities.json').write_bytes(zlib.decompress(base64.b64decode(DATA_Z)))
(ROOT/'opportunities.css').write_bytes(zlib.decompress(base64.b64decode(CSS_Z)))
print('Seeded readable data/opportunities.json and opportunities.css.')
